#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}


# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Card 19: deploy the API, the Meta Emulator (for demos) and Postgres on Railway.
# Run from the repo root: scripts/railway-deploy-wizard.sh
# Nothing is written locally: every value goes into Railway. The Claude and OpenRouter keys are read from .env.
# Stop any time and come back to a stage with FROM=N scripts/railway-deploy-wizard.sh.

ENV_FILE=.env
TOTAL_STAGES=8
FROM="${FROM:-1}"

# copy TEXT puts TEXT on the clipboard so it can be pasted into Railway, falling back to printing it.
copy() {
  if command -v pbcopy >/dev/null 2>&1; then printf '%s' "$1" | pbcopy
  elif command -v wl-copy >/dev/null 2>&1; then printf '%s' "$1" | wl-copy
  elif command -v xclip >/dev/null 2>&1; then printf '%s' "$1" | xclip -selection clipboard
  else printf '\n%s\n\n' "$1"; return
  fi
  printf '  %s✓ copiado para a área de transferência%s\n' "$GREEN" "$RESET"
}

# ask_domain KEY "Prompt" asks for a Railway domain and keeps only the host (no https://, no trailing slash).
ask_domain() {
  local attempt
  for attempt in 1 2 3; do
    ask "$1" "$2"
    printf -v "$1" '%s' "$(printf '%s' "${!1}" | sed -E 's#^https?://##; s#/.*$##')"
    [[ -n "${!1}" ]] && return
    warn "Esse valor é obrigatório."
  done
  warn "Sem domínio. Rode de novo quando tiver: FROM=$_STAGE_INDEX scripts/railway-deploy-wizard.sh"
  exit 1
}

stage_push() {
  stage "Código no GitHub"
  say "O Railway faz deploy do que está na main do GitHub, incluindo os Dockerfiles."
  if [[ -n "$(git status --porcelain)" ]]; then
    warn "Há mudanças sem commit. Elas não vão para o deploy."
  fi
  local ahead
  ahead=$(git rev-list --count origin/main..main 2>/dev/null || echo 0)
  if (( ahead > 0 )); then
    say "A main local está ${ahead} commit(s) à frente do GitHub."
    if confirm "Fazer git push origin main agora?"; then
      git push origin main
    else
      SKIPPED+=("git push origin main (o deploy usa o que está no GitHub)")
    fi
  else
    note "A main já está no GitHub."
  fi
  pause
}

stage_project() {
  stage "Projeto e serviço da API"
  open_url "https://railway.com/new"
  step "Escolha 'Deploy from GitHub repo' e o repositório cesarscf/acme (autorize o GitHub se pedir)."
  step "Clique no serviço criado > Settings e renomeie para: api"
  step "Ainda em Settings, confira se o branch do deploy é main e se Root Directory está vazio."
  note "O primeiro deploy vai falhar: ainda faltam o Dockerfile e as variáveis. Tudo bem."
  pause "Feito? Enter para continuar"
}

stage_postgres() {
  stage "Postgres"
  step "No canvas do projeto: Create (ou + New) > Database > PostgreSQL."
  step "Deixe o nome do serviço como: Postgres"
  note "A API usa \${{Postgres.DATABASE_URL}}. Se o nome for outro, ajuste na etapa 6."
  pause "Feito? Enter para continuar"
}

stage_emulator_service() {
  stage "Serviço do Meta Emulator"
  step "Create (ou + New) > GitHub Repo > cesarscf/acme de novo."
  step "Em Settings, renomeie para: meta-emulator"
  note "O nome importa: a API acha o emulador pela rede privada em meta-emulator.railway.internal."
  pause "Feito? Enter para continuar"
}

stage_domains() {
  stage "Domínios públicos"
  step "No serviço api: Settings > Networking > Public Networking > Generate Domain. Porta: 3000."
  ask_domain API_DOMAIN "Cole o domínio da API (algo.up.railway.app):"
  step "No serviço meta-emulator: o mesmo caminho. Porta: 4000."
  ask_domain EMULATOR_DOMAIN "Cole o domínio do emulador:"
  pause
}

stage_api_variables() {
  stage "Variáveis da API"
  say "Use chaves de produção, separadas das de dev, para acompanhar o gasto de cada uma."
  open_url "https://console.anthropic.com/settings/keys"
  ask_secret ANTHROPIC_API_KEY "Chave da Anthropic para produção:"
  open_url "https://openrouter.ai/settings/keys"
  ask_secret OPENROUTER_API_KEY "Chave da OpenRouter para produção:"
  [[ -z "$ANTHROPIC_API_KEY" ]] && warn "Sem chave da Anthropic: os Assistants não vão responder."
  [[ -z "$OPENROUTER_API_KEY" ]] && warn "Sem chave da OpenRouter: os áudios não vão ser transcritos."
  warn "Os segredos abaixo são gerados agora. Colar de novo num deploy existente desloga todos os Professionals."
  META_APP_SECRET=$(openssl rand -hex 32)
  META_VERIFY_TOKEN=$(openssl rand -hex 32)
  copy "RAILWAY_DOCKERFILE_PATH=/apps/api/Dockerfile
PORT=3000
DATABASE_URL=\${{Postgres.DATABASE_URL}}
BETTER_AUTH_URL=https://${API_DOMAIN}
BETTER_AUTH_SECRET=$(openssl rand -base64 32)
META_GRAPH_URL=http://\${{meta-emulator.RAILWAY_PRIVATE_DOMAIN}}:\${{meta-emulator.PORT}}
META_ACCESS_TOKEN=emulator-access-token
META_APP_SECRET=${META_APP_SECRET}
META_VERIFY_TOKEN=${META_VERIFY_TOKEN}
META_PLATFORM_PHONE_NUMBER_ID=9001
META_PLATFORM_WABA_ID=9000
ANTHROPIC_API_KEY=${ANTHROPIC_API_KEY}
ANTHROPIC_WORKSPACE_ID=$(_existing ANTHROPIC_WORKSPACE_ID || true)
CLAUDE_MODEL=$(_existing CLAUDE_MODEL || true)
OPENROUTER_API_KEY=${OPENROUTER_API_KEY}"
  step "No serviço api: Variables > Raw Editor. Cole o bloco copiado e salve."
  note "Os segredos foram gerados agora. O emulador recebe os mesmos na próxima etapa, por referência."
  step "Em Settings > Watch Paths, coloque uma por linha:"
  note "  /apps/api/**"
  note "  /packages/db/**"
  note "  /package.json"
  note "  /bun.lock"
  note "Sem NODE_ENV=production por enquanto: ele bloqueia o login pelo Expo Go (exp://)."
  pause "Colou e salvou? Enter para continuar"
}

stage_emulator_variables() {
  stage "Variáveis do Meta Emulator"
  copy "RAILWAY_DOCKERFILE_PATH=/apps/meta-emulator/Dockerfile
PORT=4000
META_APP_SECRET=\${{api.META_APP_SECRET}}
META_VERIFY_TOKEN=\${{api.META_VERIFY_TOKEN}}
META_WEBHOOK_URL=https://${API_DOMAIN}/webhooks/whatsapp"
  step "No serviço meta-emulator: Variables > Raw Editor. Cole o bloco copiado e salve."
  step "Em Settings > Watch Paths, coloque uma por linha:"
  note "  /apps/meta-emulator/**"
  note "  /packages/theme/**"
  note "  /packages/typescript-config/**"
  note "  /package.json"
  note "  /bun.lock"
  step "Faça Deploy das mudanças pendentes no topo do canvas e espere os dois serviços ficarem verdes."
  note "Se o build reclamar de arquivo não encontrado, confira se RAILWAY_DOCKERFILE_PATH começa com /."
  pause "Os dois ficaram verdes? Enter para conferir"
}

stage_check() {
  stage "Conferir o deploy"
  say "API:"
  curl -sS "https://${API_DOMAIN}/health" || true
  printf '\n'
  note "Esperado: {\"status\":\"ok\"}. As migrações rodam antes da API subir, a cada deploy."
  say "Webhook (o emulador chama a API pela URL pública HTTPS):"
  curl -sS -X POST "https://${EMULATOR_DOMAIN}/emulator/webhook/verify" || true
  printf '\n'
  note "Esperado: {\"verified\":true,\"status\":200}."
  say "Mensagem de um Customer (webhook assinado, emulador → API → Postgres):"
  curl -sS -X POST "https://${EMULATOR_DOMAIN}/emulator/conversations/9001/5511999990000/messages" \
    -H 'Content-Type: application/json' -d '{"text":"teste do deploy"}' | grep -o '"status":[0-9a-z]*}' | tail -1 || true
  note "Esperado: \"status\":200}, a resposta da API ao webhook. 401 indica META_APP_SECRET diferente nos dois serviços."
  open_url "https://${EMULATOR_DOMAIN}"
  say "Para o app no Expo Go usar a API em produção, rode em apps/mobile:"
  say "  EXPO_PUBLIC_API_URL=https://${API_DOMAIN} bun run dev"
  warn "O emulador é público e sem login: qualquer um com o link vê as mensagens da demo."
  pause
}

STAGES=(
  stage_push
  stage_project
  stage_postgres
  stage_emulator_service
  stage_domains
  stage_api_variables
  stage_emulator_variables
  stage_check
)

# Every stage waits for the human, so without a terminal on stdin (e.g. Claude Code's ! prefix) it would race through.
if [[ ! -t 0 ]]; then
  warn "Rode num terminal comum, na raiz do repo: scripts/railway-deploy-wizard.sh"
  exit 1
fi

banner "Deploy no Railway"

# Stages after the domains need them, so a run that skips ahead asks for them first.
if (( FROM > 5 )); then
  ask_domain API_DOMAIN "Domínio da API no Railway:"
  ask_domain EMULATOR_DOMAIN "Domínio do emulador no Railway:"
fi

_STAGE_INDEX=$((FROM - 1))
for stage_function in "${STAGES[@]:$((FROM - 1))}"; do
  "$stage_function"
done

finish
